923:    void assign_cells() {
924:        std::vector<BulkBucket> buckets;
925:        for (BuildNode* n : nodes_) {
926:            if (n->type != 3 || n->bulk_count == 0) continue;
927:            BulkBucket b;
928:            b.parent = n;
929:            b.stage = n->children[n->direct_count]->stage;
930:            for (int i = n->direct_count;
931:                 i < static_cast<int>(n->children.size()); ++i)
932:                b.children.push_back(n->children[i]);
933:            buckets.push_back(b);
934:        }
935:        for (int stage = 0; stage < RAM_NUM; ++stage) {
936:            uint32_t cursor = 0;
937:            for (BulkBucket& b : buckets) {
